import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Installation — Glacier","description":"Install the Glacier theme on Pterodactyl Panel via Blueprint — prerequisites, verification, troubleshooting and uninstall.","frontmatter":{"title":"Installation — Glacier","description":"Install the Glacier theme on Pterodactyl Panel via Blueprint — prerequisites, verification, troubleshooting and uninstall."},"headers":[],"relativePath":"glacier/getting-started/installation.md","filePath":"glacier/getting-started/installation.md","lastUpdated":1785230800000}'),n={name:"glacier/getting-started/installation.md"};function l(r,e,o,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Glacier ships as a single <code>.blueprint</code> package and installs through the Blueprint CLI in one command.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Version</th></tr></thead><tbody><tr><td>Pterodactyl Panel</td><td><strong>1.12.x</strong></td></tr><tr><td>Blueprint framework</td><td><strong>beta-2026-05</strong></td></tr><tr><td>PHP</td><td><strong>8.2+</strong> (as required by the panel)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Blueprint, not core edits</p><p>Glacier is a Blueprint extension. It does not patch Pterodactyl core files, so panel updates keep working — but Blueprint itself must be installed and healthy first. Verify with <code>blueprint -v</code> on the panel server.</p></div><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li><p>Download <code>glacier-v1.0.0.blueprint</code> and place it in the panel root (usually <code>/var/www/pterodactyl</code>).</p></li><li><p>From the panel root, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier-v1.0.0</span></span></code></pre></div></li><li><p>Open <strong>Admin → Extensions → Glacier</strong>. Defaults apply on first load — the panel is already themed before you touch a setting.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">First-load behavior</p><p>On its very first page load Glacier seeds every <code>glacier::*</code> setting with the documented defaults. Nothing is written to your servers, nodes, or other extensions — only rows in the panel&#39;s own settings store.</p></div><h2 id="post-install-verification" tabindex="-1">Post-install verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-install verification&quot;">​</a></h2><ol><li><strong>The sidebar appears</strong> on the left of every client page, replacing the top navigation.</li><li><strong>Admin → Extensions → Glacier</strong> loads the settings hub with the Appearance tab open and a live preview.</li><li><strong>Hard-refresh once</strong> (<code>Ctrl+Shift+R</code>) so your browser picks up the new assets. Glacier cache-busts its own assets on every save, but the first load after install may race an old cached page.</li></ol><p>If the panel ever looks unstyled after an update, clear the compiled views:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>blueprint -i</code> says the package is invalid</td><td>Upload was corrupted or renamed</td><td>Re-download; keep the exact filename <code>glacier-v1.0.0.blueprint</code></td></tr><tr><td>Extension not listed under Admin → Extensions</td><td>Blueprint cache</td><td>Run <code>blueprint -l</code> to list installed extensions; re-run the install</td></tr><tr><td>Pages render but look stock</td><td>Browser or view cache</td><td><code>php artisan view:clear</code> + hard-refresh</td></tr><tr><td>Styles missing only for admins</td><td>Same as above, admin wrapper</td><td>Same fix — both wrappers are cache-busted on save</td></tr><tr><td>Background image doesn&#39;t show</td><td>URL not reachable by browsers, or blocked hotlinking</td><td>Use the upload field instead of a URL — uploaded files are served from your own panel</td></tr><tr><td>Settings don&#39;t save (validation error)</td><td>A field outside its documented range</td><td>Check the red field hint against the <a href="./../../configuration/reference">Configuration Reference</a></td></tr></tbody></table><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> glacier</span></span></code></pre></div><p>The uninstaller makes a best-effort pass at removing Glacier&#39;s settings (<code>glacier::*</code> rows in the panel <code>settings</code> table). Your servers, users and other extensions are untouched, and the panel returns to the stock layout immediately.</p><div class="danger custom-block"><p class="custom-block-title">Other extensions&#39; theme settings</p><p>Glacier only removes its own <code>glacier::*</code> rows. If you installed other Blueprint themes previously, their leftovers are <em>not</em> Glacier&#39;s to clean — remove them with their own uninstallers.</p></div>',18)])])}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
